import sqlite3
con=sqlite3.connect('inputs/db/california_schools.sqlite')
c=con.cursor()
for col in ['GSserved','GSoffered']:
 print('\n--',col)
 for r in c.execute(f'''SELECT s.City,COUNT(*),group_concat(s.School) FROM frpm f JOIN schools s ON f.CDSCode=s.CDSCode WHERE s.Magnet=1 AND s.{col}='K-8' AND f.`NSLP Provision Status`='Multiple Provision Types' GROUP BY s.City'''):
  print(r)
# all magnet + K8 under either field and multiple
for where in ["s.GSserved='K-8'", "s.GSoffered='K-8'", "(s.GSserved='K-8' OR s.GSoffered='K-8')"]:
 print(where, c.execute(f'''SELECT COUNT(*) FROM frpm f JOIN schools s ON f.CDSCode=s.CDSCode WHERE s.Magnet=1 AND {where} AND f.`NSLP Provision Status`='Multiple Provision Types' ''').fetchone()[0])
